import React, { useState, useEffect, useRef, useCallback } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, Share2, Users, MapPin, ChevronUp, Copy, Check, LogOut, Search, Loader2, ArrowLeft, Volume2, VolumeX, ChevronDown, AlertCircle } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint | {lat: number, lng: number}, p2: GeoPoint | {lat: number, lng: number}) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

// Verifica se o ponto está próximo de qualquer segmento da rota
const isPointNearRoute = (point: GeoPoint, route: [number, number][], thresholdMeters = 100) => {
  if (!route || route.length < 2) return true;
  for (let i = 0; i < route.length; i++) {
    const dist = calculateDistance(point, { lat: route[i][0], lng: route[i][1] });
    if (dist < thresholdMeters) return true;
  }
  return false;
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [suggestions, setSuggestions] = useState<Destination[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [routeSteps, setRouteSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [isRerouting, setIsRerouting] = useState(false);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const lastSpokenStepIndexRef = useRef<number>(-1);
  const lastSpokenMilestoneRef = useRef<'far' | 'near' | null>(null);
  const lastRouteStartPosRef = useRef<GeoPoint | null>(null);
  const lastRouteDestIdRef = useRef<string | null>(null);

  const speak = useCallback((text: string) => {
    if (!isVoiceEnabled) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.0;
    utterance.pitch = 1.0;
    window.speechSynthesis.speak(utterance);
  }, [isVoiceEnabled]);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination, retryCount = 0) => {
    if (isCalculatingRoute && retryCount === 0) return;

    setIsCalculatingRoute(true);
    lastRouteStartPosRef.current = start;
    lastRouteDestIdRef.current = `${end.lat},${end.lng}`;

    try {
      // Usando OSRM com parâmetros de geometria completa e passos de navegação
      const response = await fetch(
        `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true&language=pt&continue_straight=true`
      );

      if (!response.ok) throw new Error("Servidor de rotas offline");

      const data = await response.json();
      if (data.routes && data.routes.length > 0) {
        const route = data.routes[0];
        // OSRM retorna [lng, lat], precisamos converter para [lat, lng]
        const coords = route.geometry.coordinates.map((coord: [number, number]) => [coord[1], coord[0]] as [number, number]);

        if (coords.length < 2) throw new Error("Caminho inválido retornado");

        setRouteSteps(route.legs[0].steps || []);
        setPlannedRoute(coords);
        setError(null);
        setIsRerouting(false);

        if (isRerouting) speak("Recalculando rota... siga o novo trajeto.");
      } else {
        throw new Error("Não encontramos caminhos para este destino.");
      }
    } catch (e) {
      console.error("Erro OSRM:", e);
      if (retryCount < 2) {
        setTimeout(() => fetchRoadRoute(start, end, retryCount + 1), 1500);
      } else {
        const fallbackRoute: [number, number][] = [[start.lat, start.lng], [end.lat, end.lng]];
        setPlannedRoute(fallbackRoute);
        setRouteSteps([{ maneuver: { instruction: "Siga em direção ao destino", location: [end.lng, end.lat] } }]);
        setError("Usando modo de contingência (linha reta). Verifique sua conexão.");
      }
    } finally {
      setIsCalculatingRoute(false);
    }
  };

  // Efeito principal de Geolocation e Lógica de Navegação
  useEffect(() => {
    if ("geolocation" in navigator) {
      const id = navigator.geolocation.watchPosition(
        (position) => {
          const newPoint: GeoPoint = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            timestamp: Date.now()
          };
          setUserPos(newPoint);

          // Lógica do Mestre: Gravar caminho percorrido
          if (role === UserRole.MESTRE && currentTrip?.isActive) {
            const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
            if (distanceMoved > 8) {
              const updated = storageService.updateTripPath(currentTrip.code, newPoint);
              if (updated) {
                setCurrentTrip({...updated});
                lastRecordedPosRef.current = newPoint;
              }
            }
          }

          // Lógica de Recálculo de Rota (Rerouting)
          if (currentTrip?.isActive && plannedRoute.length > 0 && !isCalculatingRoute && role === UserRole.MESTRE) {
            const isOffTrack = !isPointNearRoute(newPoint, plannedRoute, 150); // 150 metros de tolerância
            if (isOffTrack && !isRerouting) {
              setIsRerouting(true);
              if (currentTrip.destination) {
                fetchRoadRoute(newPoint, currentTrip.destination);
              }
            }
          }

          // Lógica de Voz e Passos da Navegação
          if (currentTrip?.isActive && routeSteps.length > 0) {
            const nextStep = routeSteps[currentStepIndex];
            if (nextStep) {
              const stepPos = { lat: nextStep.maneuver.location[1], lng: nextStep.maneuver.location[0] };
              const distToStep = calculateDistance(newPoint, stepPos);

              // Alerta antecipado (250 metros)
              if (distToStep <= 250 && distToStep > 60) {
                if (lastSpokenStepIndexRef.current !== currentStepIndex || lastSpokenMilestoneRef.current !== 'far') {
                  speak(`Em duzentos e cinquenta metros, ${nextStep.maneuver.instruction}`);
                  lastSpokenStepIndexRef.current = currentStepIndex;
                  lastSpokenMilestoneRef.current = 'far';
                }
              }

              // Alerta imediato (50 metros)
              if (distToStep <= 55) {
                if (lastSpokenMilestoneRef.current !== 'near') {
                  speak(nextStep.maneuver.instruction);
                  lastSpokenStepIndexRef.current = currentStepIndex;
                  lastSpokenMilestoneRef.current = 'near';

                  // Avança para o próximo passo após a manobra
                  if (currentStepIndex < routeSteps.length - 1) {
                    setTimeout(() => {
                        setCurrentStepIndex(prev => prev + 1);
                        lastSpokenMilestoneRef.current = null;
                    }, 5000);
                  }
                }
              }
            }
          }
        },
        () => setError("Erro ao obter GPS. Verifique as permissões do navegador."),
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
      watchIdRef.current = id;
    }
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, [role, currentTrip, routeSteps, currentStepIndex, plannedRoute, isCalculatingRoute, isRerouting, speak]);

  // Sincronização Seguidor-Mestre
  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip(prev => {
            if (prev && JSON.stringify(prev.path) !== JSON.stringify(trip.path)) {
               return {...trip};
            }
            return prev;
          });
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
          if (trip.plannedRoute) setPlannedRoute(trip.plannedRoute);
        }
      }, 4000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  // Busca de Destinos com Gemini
  useEffect(() => {
    if (selectedDest && searchQuery === selectedDest.name) {
      setSuggestions([]);
      return;
    }
    if (searchQuery.length < 3) {
      setSuggestions([]);
      return;
    }
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const locationContext = userPos ? `O usuário está em Lat: ${userPos.lat}, Lng: ${userPos.lng}. ` : "";
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `Atue como um buscador de endereços. Sugira 5 locais reais e precisos para a busca: "${searchQuery}". ${locationContext} Priorize resultados na mesma cidade ou estado. Retorne APENAS um array JSON válido com campos: name (string), address (string), lat (number), lng (number).`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  lat: { type: Type.NUMBER },
                  lng: { type: Type.NUMBER },
                  name: { type: Type.STRING },
                  address: { type: Type.STRING }
                },
                required: ["lat", "lng", "name", "address"]
              }
            }
          }
        });
        if (response && response.text) {
          setSuggestions(JSON.parse(response.text));
        }
      } catch (err) {
        console.error("Erro Gemini Search:", err);
      } finally {
        setIsSearching(false);
      }
    }, 800);
    return () => { if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current); };
  }, [searchQuery, userPos, selectedDest]);

  // Monitor de mudança de destino para recalculação
  useEffect(() => {
    if (selectedDest && userPos) {
      const destId = `${selectedDest.lat},${selectedDest.lng}`;
      if (destId !== lastRouteDestIdRef.current || plannedRoute.length === 0) {
        fetchRoadRoute(userPos, selectedDest);
      }
    }
  }, [selectedDest, userPos?.lat, userPos?.lng]);

  const handleSelectSuggestion = (suggestion: Destination) => {
    setSelectedDest(suggestion);
    setSearchQuery(suggestion.name);
    setSuggestions([]);
    setPlannedRoute([]);
    setRouteSteps([]);
  };

  const handleStartTrip = async () => {
    if (!selectedDest || isCalculatingRoute) return;

    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: `Comboio para ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };

    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    lastRecordedPosRef.current = userPos;
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(false);
    setCurrentStepIndex(0);
    lastSpokenStepIndexRef.current = -1;
    lastSpokenMilestoneRef.current = null;

    speak("Viagem iniciada. Siga o traçado azul no mapa para chegar ao seu destino.");
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center animate-in fade-in zoom-in duration-700">
          <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-[0_20px_50px_rgba(37,99,235,0.4)]">
            <Navigation size={48} className="text-white fill-white/20" />
          </div>
          <h1 className="text-5xl font-black mb-3 tracking-tighter">Siga o Mestre</h1>
          <p className="text-slate-400 text-lg font-medium">Navegação inteligente em comboio.</p>
        </div>
        <div className="w-full max-w-sm space-y-5">
          <button onClick={() => { setIsConfiguringTrip(true); setSelectedDest(null); setPlannedRoute([]); setSearchQuery(''); }} className="group w-full bg-blue-600 text-white font-bold py-6 px-6 rounded-3xl flex items-center justify-between shadow-2xl active:scale-95 transition-all">
            <div className="flex items-center"><Play size={28} className="mr-4 fill-white"/> Criar Comboio (Mestre)</div>
            <ChevronUp className="rotate-90 opacity-40 group-hover:opacity-100 transition-opacity" />
          </button>
          <div className="relative py-4">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div>
            <div className="relative flex justify-center text-xs"><span className="bg-[#0f172a] px-4 text-slate-500 font-black tracking-widest uppercase">Ou entre num grupo</span></div>
          </div>
          <div className="space-y-3">
            <input type="text" placeholder="CÓDIGO" className="w-full bg-slate-800/50 border-2 border-slate-700/50 rounded-2xl px-5 py-5 text-white uppercase text-center text-2xl font-mono font-black tracking-[0.3em] focus:border-blue-500 focus:ring-4 focus:ring-blue-500/20 transition-all outline-none" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
            <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); setPlannedRoute(trip.plannedRoute || []); setIsBottomSheetOpen(false); }else{ setError("Código inválido ou expirado."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-black py-5 px-6 rounded-2xl flex items-center justify-center active:scale-95 transition-all disabled:opacity-50 shadow-xl">
              <Users size={24} className="mr-3" /> Entrar como Seguidor
            </button>
          </div>
          {error && <div className="flex items-center justify-center text-red-400 text-sm font-bold bg-red-500/10 p-3 rounded-xl border border-red-500/20 animate-bounce"><AlertCircle size={16} className="mr-2" /> {error}</div>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white overflow-hidden z-[2000]">
        <div className="relative h-16 bg-slate-900 text-white flex items-center px-4 shrink-0 z-50 shadow-lg">
          <button onClick={() => setIsConfiguringTrip(false)} className="flex items-center text-slate-400 px-2 font-bold">
            <ArrowLeft className="mr-2" size={20} /> Voltar
          </button>
          <div className="flex-1 text-center font-black text-lg tracking-tight">Novo Comboio</div>
          <div className="w-10"></div>
        </div>

        <div className="flex-grow relative w-full overflow-hidden bg-slate-100">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => handleSelectSuggestion({ lat, lng, name: "Local no Mapa", address: "Ponto personalizado" })}
            isSelectingDestination={true}
          />

          <div className="absolute top-4 left-4 right-4 z-[3000]">
            <div className="relative flex shadow-[0_8px_30px_rgba(0,0,0,0.15)] bg-white rounded-2xl overflow-hidden border border-slate-100 focus-within:ring-4 focus-within:ring-blue-500/20 transition-all">
              <div className="flex items-center pl-4 text-slate-400">
                {isSearching ? <Loader2 size={24} className="animate-spin text-blue-500" /> : <Search size={24} />}
              </div>
              <input 
                type="text" 
                placeholder="Para onde vamos hoje?" 
                className="w-full px-4 py-5 border-none focus:ring-0 text-slate-900 font-bold text-lg placeholder:text-slate-400 placeholder:font-normal"
                value={searchQuery}
                onChange={(e) => {
                    setSearchQuery(e.target.value);
                    if(selectedDest && e.target.value !== selectedDest.name) {
                      setSelectedDest(null);
                      setPlannedRoute([]);
                    }
                }}
              />
            </div>

            {suggestions.length > 0 && !selectedDest && (
              <div className="mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden max-h-[60vh] overflow-y-auto animate-in fade-in slide-in-from-top-4">
                {suggestions.map((item, idx) => (
                  <button key={idx} onClick={() => handleSelectSuggestion(item)} className="w-full px-5 py-5 flex items-start space-x-4 hover:bg-blue-50 border-b border-slate-50 last:border-b-0 text-left transition-colors">
                    <div className="bg-slate-100 p-2 rounded-lg text-slate-400 group-hover:text-blue-500"><MapPin size={20} /></div>
                    <div className="flex-1 min-w-0">
                      <div className="font-bold text-slate-900 truncate text-lg leading-tight">{item.name}</div>
                      <div className="text-sm text-slate-400 truncate mt-1">{item.address}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {selectedDest && (
            <div className="absolute bottom-8 left-4 right-4 z-[2000] bg-white p-6 rounded-[2.5rem] shadow-[0_30px_80px_rgba(0,0,0,0.3)] animate-in slide-in-from-bottom duration-500 border border-slate-100">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-50 p-4 rounded-3xl shrink-0 flex items-center justify-center border border-blue-100">
                  {isCalculatingRoute ? <Loader2 className="text-blue-600 animate-spin" size={32} /> : <MapPin className="text-blue-600 fill-blue-600/20" size={32} />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-1">
                    {isCalculatingRoute ? 'Calculando melhor caminho...' : 'Destino Confirmado'}
                  </div>
                  <div className="text-slate-900 font-black text-2xl leading-tight truncate">{selectedDest.name}</div>
                  <div className="text-sm text-slate-400 truncate font-medium mt-1">{selectedDest.address}</div>
                </div>
              </div>
              <button 
                onClick={handleStartTrip} 
                disabled={isCalculatingRoute || plannedRoute.length === 0}
                className={`w-full text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all flex items-center justify-center text-xl ${isCalculatingRoute || plannedRoute.length === 0 ? 'bg-slate-300' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-500/40'}`}
              >
                {isCalculatingRoute ? 'Aguarde...' : 'Começar a Dirigir'}
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 w-full h-full overflow-hidden bg-slate-900">
      <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />

      {/* Interface de Topo (Informações e Status) */}
      <div className="absolute top-4 left-4 right-4 z-[500] flex flex-col space-y-3 pointer-events-none">
        <div className="bg-white/90 backdrop-blur-xl rounded-3xl p-4 shadow-2xl flex items-center justify-between border border-white pointer-events-auto">
          <div className="flex items-center space-x-4">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600 shadow-blue-500/50' : 'bg-red-500 shadow-red-500/50'} w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg text-2xl`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-black text-slate-900 text-lg leading-tight">
                {role === UserRole.MESTRE ? 'Você é o Mestre' : 'Seguindo Mestre'}
              </h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div> AO VIVO
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <button onClick={() => { const nextState = !isVoiceEnabled; setIsVoiceEnabled(nextState); if(nextState) speak("Voz ativada."); }} className={`p-3.5 rounded-2xl transition-all ${isVoiceEnabled ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
               {isVoiceEnabled ? <Volume2 size={24} /> : <VolumeX size={24} />}
             </button>
             <button onClick={() => { if(window.confirm("Deseja sair deste comboio?")) { setRole(UserRole.NONE); setCurrentTrip(null); } }} className="p-3.5 text-slate-400 hover:text-red-500 bg-slate-50 rounded-2xl shadow-inner active:scale-90 transition-all border border-slate-100">
               <LogOut size={24} />
             </button>
          </div>
        </div>

        {/* Banner de Próxima Manobra (Estilo Waze) */}
        {currentTrip?.isActive && routeSteps[currentStepIndex] && (
          <div className="bg-blue-600 text-white p-5 rounded-[2rem] shadow-[0_20px_40px_rgba(37,99,235,0.4)] border-b-8 border-blue-800 animate-in slide-in-from-top-8 duration-500 pointer-events-auto">
            <div className="flex items-center space-x-5">
               <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-md"><Navigation size={32} className="rotate-45 fill-white" /></div>
               <div className="flex-1">
                  <div className="text-[10px] font-black text-blue-100 uppercase tracking-widest mb-1 opacity-80">Próxima Instrução</div>
                  <div className="font-black text-xl leading-tight">{routeSteps[currentStepIndex].maneuver.instruction}</div>
               </div>
            </div>
