        {/* Indicador de Recálculo */}
        {isRerouting && (
           <div className="self-center bg-amber-500 text-white px-6 py-2 rounded-full font-black text-xs uppercase tracking-widest shadow-lg animate-pulse border-2 border-white">
              Recalculando Caminho...
           </div>
        )}
