      {/* Bottom Sheet (Painel de Controle) */}
      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-[0_-20px_60px_rgba(0,0,0,0.15)] rounded-t-[3rem] z-[1000] transition-all duration-700 ease-[cubic-bezier(0.2,0.8,0.2,1)] ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-90px)]'}`}>
        <div className="w-full flex flex-col items-center py-5 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-16 h-1.5 bg-slate-200 rounded-full mb-2"></div>
          {!isBottomSheetOpen && <div className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] py-2">Detalhes da Viagem</div>}
          {isBottomSheetOpen && <ChevronDown size={24} className="text-slate-300" />}
        </div>

        <div className="px-8 pb-12 space-y-6">
          <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between">
            <div className="flex-1">
               <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Código do Grupo</div>
               <div className="text-4xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
