import React, { useEffect, useRef, useState } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, useMap, ZoomControl, useMapEvents, Circle } from 'react-leaflet';
import L from 'leaflet';
import { Trip, GeoPoint, UserRole, Destination } from '../types';

interface MapProps {
  userPos: GeoPoint | null;
  masterPos: GeoPoint | null;
  trip: Trip | null;
  role: UserRole;
  onMapClick?: (lat: number, lng: number) => void;
  isSelectingDestination?: boolean;
}

const MapController: React.FC<{ 
  tripId?: string; 
  pos: GeoPoint | null; 
  plannedRoute?: [number, number][]; 
  isActive: boolean 
}> = ({ tripId, pos, plannedRoute, isActive }) => {
  const map = useMap();
  const initialFitRef = useRef<string | null>(null);
  const [isFollowing, setIsFollowing] = useState(true);

  useMapEvents({
    dragstart: () => {
      if (isActive) setIsFollowing(false);
    },
  });

  useEffect(() => {
    const timer = setTimeout(() => {
      map.invalidateSize();
    }, 300);
    return () => clearTimeout(timer);
  }, [map]);

  useEffect(() => {
    if (tripId && initialFitRef.current !== tripId) {
      if (plannedRoute && plannedRoute.length > 5) {
        const bounds = L.latLngBounds(plannedRoute);
        map.fitBounds(bounds, { padding: [100, 100], maxZoom: 16 });
        initialFitRef.current = tripId;
        setIsFollowing(true);
      } else if (pos) {
        map.setView([pos.lat, pos.lng], 16);
        initialFitRef.current = tripId;
        setIsFollowing(true);
      }
    }
    if (!tripId) initialFitRef.current = null;
  }, [tripId, plannedRoute, pos, map]);

  useEffect(() => {
    if (isActive && pos && isFollowing) {
      map.setView([pos.lat, pos.lng], Math.max(map.getZoom(), 16), { 
        animate: true, 
        duration: 1.5 
      });
    }
  }, [pos?.lat, pos?.lng, isActive, isFollowing, map]);

  return (
    isActive && !isFollowing ? (
      <div className="absolute bottom-36 right-6 z-[1000]">
        <button 
          onClick={() => setIsFollowing(true)}
          className="bg-blue-600 text-white p-4 rounded-full shadow-[0_15px_30px_rgba(37,99,235,0.4)] active:scale-90 transition-all border-4 border-white"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="rotate-45"><polygon points="3 11 22 2 13 21 11 13 3 11"/></svg>
        </button>
      </div>
    ) : null
  );
};

const MapEvents: React.FC<{ onClick: (lat: number, lng: number) => void }> = ({ onClick }) => {
  useMapEvents({
    click: (e) => onClick(e.latlng.lat, e.latlng.lng),
  });
  return null;
};

const MapComponent: React.FC<MapProps> = ({ userPos, masterPos, trip, role, onMapClick, isSelectingDestination }) => {
  const masterIcon = L.divIcon({
    className: 'custom-div-icon',
    html: `<div style="background-color: #2563eb; width: 36px; height: 36px; border-radius: 50%; border: 4px solid white; box-shadow: 0 4px 15px rgba(0,0,0,0.3); display: flex; align-items: center; justify-content: center; font-size: 16px;">👑</div>`,
    iconSize: [36, 36],
    iconAnchor: [18, 18]
  });

  const followerIcon = L.divIcon({
    className: 'custom-div-icon',
    html: `<div style="background-color: #ef4444; width: 32px; height: 32px; border-radius: 50%; border: 4px solid white; box-shadow: 0 4px 15px rgba(0,0,0,0.3); display: flex; align-items: center; justify-content: center; font-size: 14px;">🚗</div>`,
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const destIcon = L.divIcon({
    className: 'custom-div-icon',
    html: `<div style="background-color: #0f172a; width: 40px; height: 40px; border-radius: 14px; border: 4px solid white; box-shadow: 0 8px 25px rgba(0,0,0,0.4); display: flex; align-items: center; justify-content: center; font-size: 20px;">🏁</div>`,
    iconSize: [40, 40],
    iconAnchor: [20, 20]
  });

  // Rota vinda do Mestre ou calculada localmente
  const routePoints = trip?.plannedRoute || [];
  const recordedPath = trip?.path.map(p => [p.lat, p.lng] as [number, number]) || [];

  return (
    <div className="absolute inset-0 w-full h-full bg-slate-100">
      <MapContainer
        center={userPos ? [userPos.lat, userPos.lng] : [-23.5505, -46.6333]}
        zoom={16}
        zoomControl={false}
        className="w-full h-full"
      >
        <TileLayer
          attribution='&copy; OpenStreetMap'
          url="https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png"
        />
        <ZoomControl position="bottomright" />

        {isSelectingDestination && onMapClick && <MapEvents onClick={onMapClick} />}

        {/* ROTA ESTILO WAZE: Camadas para profundidade e brilho */}
        {routePoints.length > 2 && (
          <>
            {/* 1. Sombra/Borda Externa */}
            <Polyline 
              positions={routePoints} 
              pathOptions={{ color: '#1e40af', weight: 14, opacity: 0.2, lineJoin: 'round', lineCap: 'round' }} 
            />
            {/* 2. Glow Interno */}
            <Polyline 
              positions={routePoints} 
              pathOptions={{ color: '#3b82f6', weight: 10, opacity: 0.5, lineJoin: 'round', lineCap: 'round' }} 
            />
            {/* 3. Linha Principal (Central) */}
            <Polyline 
              positions={routePoints} 
              pathOptions={{ color: '#60a5fa', weight: 5, opacity: 1, lineJoin: 'round', lineCap: 'round' }} 
            />
          </>
        )}

        {/* Rastro real percorrido (Verde para indicar o caminho exato feito) */}
        {recordedPath.length > 1 && (
          <Polyline 
            positions={recordedPath} 
            pathOptions={{ color: '#10b981', weight: 8, opacity: 0.5, lineJoin: 'round', lineCap: 'round', dashArray: '1, 12' }}
          />
        )}

        {trip?.destination && (
          <Marker position={[trip.destination.lat, trip.destination.lng]} icon={destIcon} />
        )}

        {userPos && (
          <Circle 
            center={[userPos.lat, userPos.lng]} 
            radius={20} 
            pathOptions={{ fillColor: '#3b82f6', fillOpacity: 0.15, color: 'transparent' }} 
          />
        )}

        {userPos && (
          <Marker 
            position={[userPos.lat, userPos.lng]} 
            icon={role === UserRole.MESTRE ? masterIcon : followerIcon} 
            zIndexOffset={1000}
          />
        )}

        {role === UserRole.SEGUIDOR && masterPos && (
          <Marker 
            position={[masterPos.lat, masterPos.lng]} 
            icon={masterIcon} 
            zIndexOffset={950}
          />
        )}

        <MapController 
          tripId={trip?.id}
          pos={userPos} 
          plannedRoute={routePoints} 
          isActive={!!trip && trip.isActive}
        />
      </MapContainer>
    </div>
  );
};

export default MapComponent;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, Share2, Users, MapPin, ChevronUp, Copy, Check, LogOut, Search, Loader2, ArrowLeft, Volume2, VolumeX, ChevronDown, AlertCircle } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint | {lat: number, lng: number}, p2: GeoPoint | {lat: number, lng: number}) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const isPointNearRoute = (point: GeoPoint, route: [number, number][], thresholdMeters = 100) => {
  if (!route || route.length < 2) return true;
  // Checa apenas os pontos mais próximos para performance
  for (let i = 0; i < route.length; i += Math.max(1, Math.floor(route.length / 20))) {
    const dist = calculateDistance(point, { lat: route[i][0], lng: route[i][1] });
    if (dist < thresholdMeters) return true;
  }
  return false;
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [suggestions, setSuggestions] = useState<Destination[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [routeSteps, setRouteSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [isRerouting, setIsRerouting] = useState(false);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const lastSpokenStepIndexRef = useRef<number>(-1);
  const lastSpokenMilestoneRef = useRef<'far' | 'near' | null>(null);
  const lastRouteDestIdRef = useRef<string | null>(null);

  const speak = useCallback((text: string) => {
    if (!isVoiceEnabled) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  }, [isVoiceEnabled]);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    setIsCalculatingRoute(true);
    lastRouteDestIdRef.current = `${end.lat},${end.lng}`;

    try {
      // OSRM: Extrai a rota real pelas ruas com alta fidelidade (overview=full)
      const response = await fetch(
        `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true&language=pt`
      );

      const data = await response.json();
      if (data.routes && data.routes.length > 0) {
        const route = data.routes[0];
        // IMPORTANTE: OSRM retorna [longitude, latitude], Leaflet usa [latitude, longitude]
        const coords: [number, number][] = route.geometry.coordinates.map((c: any) => [c[1], c[0]]);

        if (coords.length < 3) {
           throw new Error("A API retornou uma linha reta ou rota muito curta.");
        }

        setPlannedRoute(coords);
        setRouteSteps(route.legs[0].steps || []);
        setError(null);
        setIsRerouting(false);
        if (isRerouting) speak("Rota atualizada.");
      } else {
        throw new Error("Nenhuma rota encontrada pelas ruas.");
      }
    } catch (e) {
      console.error("Erro de Roteamento:", e);
      setError("Não foi possível traçar a rota exata pelas ruas. Tente novamente.");
      setPlannedRoute([]);
    } finally {
      setIsCalculatingRoute(false);
    }
  };

  useEffect(() => {
    if ("geolocation" in navigator) {
      const id = navigator.geolocation.watchPosition(
        (position) => {
          const newPoint: GeoPoint = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            timestamp: Date.now()
          };
          setUserPos(newPoint);

          if (role === UserRole.MESTRE && currentTrip?.isActive) {
            const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
            if (distanceMoved > 10) {
              const updated = storageService.updateTripPath(currentTrip.code, newPoint);
              if (updated) {
                setCurrentTrip({...updated});
                lastRecordedPosRef.current = newPoint;
              }
            }
          }

          // Lógica de Recálculo (Rerouting)
          if (role === UserRole.MESTRE && currentTrip?.isActive && plannedRoute.length > 0 && !isCalculatingRoute) {
            if (!isPointNearRoute(newPoint, plannedRoute, 150)) {
               setIsRerouting(true);
               if (currentTrip.destination) fetchRoadRoute(newPoint, currentTrip.destination);
            }
          }

          // Voz e Instruções
          if (currentTrip?.isActive && routeSteps.length > 0) {
            const nextStep = routeSteps[currentStepIndex];
            if (nextStep) {
              const stepPos = { lat: nextStep.maneuver.location[1], lng: nextStep.maneuver.location[0] };
              const distToStep = calculateDistance(newPoint, stepPos);

              if (distToStep <= 300 && distToStep > 60) {
                if (lastSpokenStepIndexRef.current !== currentStepIndex || lastSpokenMilestoneRef.current !== 'far') {
                  speak(`Em trezentos metros, ${nextStep.maneuver.instruction}`);
                  lastSpokenStepIndexRef.current = currentStepIndex;
                  lastSpokenMilestoneRef.current = 'far';
                }
              }

              if (distToStep <= 50) {
                if (lastSpokenMilestoneRef.current !== 'near') {
                  speak(nextStep.maneuver.instruction);
                  lastSpokenStepIndexRef.current = currentStepIndex;
                  lastSpokenMilestoneRef.current = 'near';
                  if (currentStepIndex < routeSteps.length - 1) {
                    setTimeout(() => {
                      setCurrentStepIndex(prev => prev + 1);
                      lastSpokenMilestoneRef.current = null;
                    }, 4000);
                  }
                }
              }
            }
          }
        },
        () => setError("Permita o acesso ao GPS para navegar."),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
      watchIdRef.current = id;
    }
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, [role, currentTrip, routeSteps, currentStepIndex, plannedRoute, isCalculatingRoute, isRerouting, speak]);

  // Sincronização constante com o Mestre (para o Seguidor)
  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip({...trip});
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
          if (trip.plannedRoute) setPlannedRoute(trip.plannedRoute);
        }
      }, 3000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  useEffect(() => {
    if (selectedDest && searchQuery === selectedDest.name) return;
    if (searchQuery.length < 3) { setSuggestions([]); return; }
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `Busque 5 locais para: "${searchQuery}". Local atual: ${userPos?.lat}, ${userPos?.lng}. JSON com name, address, lat, lng.`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  lat: { type: Type.NUMBER },
                  lng: { type: Type.NUMBER },
                  name: { type: Type.STRING },
                  address: { type: Type.STRING }
                },
                required: ["lat", "lng", "name", "address"]
              }
            }
          }
        });
        if (response?.text) setSuggestions(JSON.parse(response.text));
      } catch (err) { console.error(err); } finally { setIsSearching(false); }
    }, 800);
  }, [searchQuery, userPos]);

  useEffect(() => {
    if (selectedDest && userPos) {
      const destId = `${selectedDest.lat},${selectedDest.lng}`;
      if (destId !== lastRouteDestIdRef.current || plannedRoute.length === 0) {
        fetchRoadRoute(userPos, selectedDest);
      }
    }
  }, [selectedDest, userPos]);

  const handleStartTrip = async () => {
    if (!selectedDest || plannedRoute.length < 3) return;

    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: `Comboio para ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute, // Aqui enviamos a polilinha completa das ruas
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };

    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(false);
    speak("Comboio iniciado. Siga o traçado destacado no mapa.");
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center">
          <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <Navigation size={48} className="text-white" />
          </div>
          <h1 className="text-5xl font-black mb-3 tracking-tighter">Siga o Mestre</h1>
          <p className="text-slate-400 text-lg">Comboio inteligente pelas ruas.</p>
        </div>
        <div className="w-full max-w-sm space-y-5">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 text-white font-bold py-6 px-6 rounded-3xl flex items-center justify-between shadow-xl active:scale-95 transition-all">
            <div className="flex items-center"><Play size={28} className="mr-4 fill-white"/> Criar Comboio</div>
            <ChevronUp className="rotate-90 opacity-40" />
          </button>
          <div className="relative py-4"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div><div className="relative flex justify-center text-xs"><span className="bg-[#0f172a] px-4 text-slate-500 font-black uppercase">Ou</span></div></div>
          <div className="space-y-3">
            <input type="text" placeholder="CÓDIGO" className="w-full bg-slate-800/50 border-2 border-slate-700/50 rounded-2xl px-5 py-5 text-white uppercase text-center text-2xl font-mono font-black tracking-widest outline-none focus:border-blue-500" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
            <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); setPlannedRoute(trip.plannedRoute || []); setIsBottomSheetOpen(false); }else{ setError("Código inválido."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-black py-5 px-6 rounded-2xl flex items-center justify-center active:scale-95 transition-all shadow-xl">
              <Users size={24} className="mr-3" /> Entrar como Seguidor
            </button>
          </div>
          {error && <div className="text-red-400 text-sm font-bold bg-red-500/10 p-3 rounded-xl border border-red-500/20 text-center">{error}</div>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white overflow-hidden z-[2000]">
        <div className="relative h-16 bg-slate-900 text-white flex items-center px-4 shrink-0 z-50">
          <button onClick={() => setIsConfiguringTrip(false)} className="flex items-center text-slate-400 font-bold"><ArrowLeft className="mr-2" size={20} /> Voltar</button>
          <div className="flex-1 text-center font-black">Definir Trajeto</div>
          <div className="w-10"></div>
        </div>

        <div className="flex-grow relative w-full overflow-hidden">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => setSelectedDest({ lat, lng, name: "Ponto no Mapa", address: "Localização personalizada" })}
            isSelectingDestination={true}
          />

          <div className="absolute top-4 left-4 right-4 z-[3000]">
            <div className="relative flex shadow-xl bg-white rounded-2xl overflow-hidden border border-slate-100">
              <div className="flex items-center pl-4 text-slate-400">{isSearching ? <Loader2 size={24} className="animate-spin text-blue-500" /> : <Search size={24} />}</div>
              <input type="text" placeholder="Para onde vamos?" className="w-full px-4 py-5 border-none focus:ring-0 text-slate-900 font-bold" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
            </div>
            {suggestions.length > 0 && !selectedDest && (
              <div className="mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden max-h-[50vh] overflow-y-auto">
                {suggestions.map((item, idx) => (
                  <button key={idx} onClick={() => { setSelectedDest(item); setSearchQuery(item.name); setSuggestions([]); }} className="w-full px-5 py-4 flex items-start space-x-4 hover:bg-blue-50 border-b border-slate-50 last:border-b-0 text-left">
                    <MapPin size={20} className="text-slate-400 mt-1" />
                    <div className="flex-1 truncate">
                      <div className="font-bold text-slate-900 truncate">{item.name}</div>
                      <div className="text-sm text-slate-400 truncate">{item.address}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {selectedDest && (
            <div className="absolute bottom-8 left-4 right-4 z-[2000] bg-white p-6 rounded-[2.5rem] shadow-2xl border border-slate-100 animate-in slide-in-from-bottom duration-500">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-50 p-4 rounded-2xl shrink-0 flex items-center justify-center">
                  {isCalculatingRoute ? <Loader2 className="text-blue-600 animate-spin" size={32} /> : <MapPin className="text-blue-600" size={32} />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">{isCalculatingRoute ? 'Calculando Trajeto...' : 'Destino Selecionado'}</div>
                  <div className="text-slate-900 font-black text-2xl truncate">{selectedDest.name}</div>
                </div>
              </div>
              <button onClick={handleStartTrip} disabled={isCalculatingRoute || plannedRoute.length < 3} className={`w-full text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl ${isCalculatingRoute || plannedRoute.length < 3 ? 'bg-slate-300 cursor-not-allowed' : 'bg-blue-600 shadow-blue-500/40'}`}>
                {isCalculatingRoute ? 'Calculando...' : 'Iniciar Comboio'}
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 w-full h-full overflow-hidden bg-slate-900">
      <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />

      <div className="absolute top-4 left-4 right-4 z-[500] flex flex-col space-y-3 pointer-events-none">
        <div className="bg-white/95 backdrop-blur-xl rounded-[2rem] p-4 shadow-2xl flex items-center justify-between border border-white pointer-events-auto">
          <div className="flex items-center space-x-4">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg text-2xl`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-black text-slate-900 text-lg leading-tight">{role === UserRole.MESTRE ? 'Você é o Mestre' : 'Seguindo o Mestre'}</h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1"><div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div> AO VIVO</div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <button onClick={() => setIsVoiceEnabled(!isVoiceEnabled)} className={`p-3.5 rounded-2xl transition-all ${isVoiceEnabled ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
               {isVoiceEnabled ? <Volume2 size={24} /> : <VolumeX size={24} />}
             </button>
             <button onClick={() => { if(window.confirm("Sair do comboio?")) { setRole(UserRole.NONE); setCurrentTrip(null); } }} className="p-3.5 text-slate-400 hover:text-red-500 bg-slate-50 rounded-2xl shadow-inner active:scale-90 transition-all border border-slate-100">
               <LogOut size={24} />
             </button>
          </div>
        </div>

        {currentTrip?.isActive && routeSteps[currentStepIndex] && (
          <div className="bg-blue-600 text-white p-5 rounded-[2rem] shadow-2xl border-b-8 border-blue-800 animate-in slide-in-from-top duration-500 pointer-events-auto">
            <div className="flex items-center space-x-5">
               <div className="bg-white/20 p-3 rounded-2xl"><Navigation size={32} className="rotate-45" /></div>
               <div className="flex-1">
                  <div className="text-[10px] font-black text-blue-100 uppercase tracking-widest mb-1">Próxima Instrução</div>
                  <div className="font-black text-xl leading-tight">{routeSteps[currentStepIndex].maneuver.instruction}</div>
               </div>
            </div>
          </div>
        )}

        {isRerouting && <div className="self-center bg-amber-500 text-white px-6 py-2 rounded-full font-black text-xs uppercase tracking-widest shadow-lg animate-pulse border-2 border-white">Recalculando...</div>}
      </div>

      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-2xl rounded-t-[3rem] z-[1000] transition-all duration-700 ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-90px)]'}`}>
        <div className="w-full flex flex-col items-center py-5 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-16 h-1.5 bg-slate-200 rounded-full mb-2"></div>
          {!isBottomSheetOpen && <div className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] py-2">Painel de Controle</div>}
          {isBottomSheetOpen && <ChevronDown size={24} className="text-slate-300" />}
        </div>

        <div className="px-8 pb-12 space-y-6">
          <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between">
            <div className="flex-1">
               <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Código do Grupo</div>
               <div className="text-4xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="p-5 bg-white rounded-2xl shadow-md text-blue-600 active:scale-90 transition-all border border-slate-50">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
            </button>
          </div>

          {currentTrip?.destination && (
            <div className="flex items-center space-x-5 text-slate-600 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
              <div className="bg-blue-100 p-3 rounded-xl"><MapPin size={28} className="text-blue-600" /></div>
              <div className="flex-1 truncate">
                <div className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-0.5">Destino Final</div>
                <div className="font-black text-xl text-slate-800 truncate">{currentTrip.destination.name}</div>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 gap-4 pt-2">
            {role === UserRole.MESTRE && (
              <button onClick={() => { if(window.confirm("Encerrar viagem?")) { if(currentTrip) storageService.saveTrip({...currentTrip, isActive: false}); setCurrentTrip(null); setRole(UserRole.NONE); } }} className="w-full bg-red-500 text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl">Encerrar Viagem</button>
            )}
            <button onClick={() => window.open(`https://wa.me/?text=Código do Comboio Siga o Mestre: ${currentTrip?.code}`, '_blank')} className="w-full border-2 border-slate-100 py-5 rounded-3xl font-black text-slate-600 flex items-center justify-center hover:bg-slate-50 transition-colors">
              <Share2 className="mr-3" size={24} /> Compartilhar Código
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, Share2, Users, MapPin, ChevronUp, Copy, Check, LogOut, Search, Loader2, ArrowLeft, Volume2, VolumeX, ChevronDown, AlertCircle } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint | {lat: number, lng: number}, p2: GeoPoint | {lat: number, lng: number}) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const isPointNearRoute = (point: GeoPoint, route: [number, number][], thresholdMeters = 100) => {
  if (!route || route.length < 2) return true;
  for (let i = 0; i < route.length; i += Math.max(1, Math.floor(route.length / 15))) {
    const dist = calculateDistance(point, { lat: route[i][0], lng: route[i][1] });
    if (dist < thresholdMeters) return true;
  }
  return false;
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [suggestions, setSuggestions] = useState<Destination[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [routeSteps, setRouteSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [isRerouting, setIsRerouting] = useState(false);

  // Refs para evitar reinicialização do GPS
  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fetchInProgressRef = useRef<boolean>(false);

  // Refs de Navegação (acessadas dentro do watchPosition sem disparar efeito)
  const navDataRef = useRef({
    role,
    isActive: false,
    plannedRoute: [] as [number, number][],
    routeSteps: [] as any[],
    currentStepIndex: 0,
    isCalculating: false,
    destination: null as Destination | null,
    tripCode: ''
  });

  // Sincronizar refs com estado
  useEffect(() => {
    navDataRef.current = {
      role,
      isActive: currentTrip?.isActive || false,
      plannedRoute,
      routeSteps,
      currentStepIndex,
      isCalculating: isCalculatingRoute,
      destination: selectedDest || currentTrip?.destination || null,
      tripCode: currentTrip?.code || ''
    };
  }, [role, currentTrip, plannedRoute, routeSteps, currentStepIndex, isCalculatingRoute, selectedDest]);

  const lastSpokenRef = useRef({ index: -1, milestone: null as string | null });

  const speak = useCallback((text: string) => {
    if (!isVoiceEnabled) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  }, [isVoiceEnabled]);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    if (fetchInProgressRef.current) return;
    fetchInProgressRef.current = true;
    setIsCalculatingRoute(true);

    try {
      const response = await fetch(
        `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true&language=pt`
      );

      const data = await response.json();
      if (data.routes && data.routes.length > 0) {
        const route = data.routes[0];
        const coords: [number, number][] = route.geometry.coordinates.map((c: any) => [c[1], c[0]]);

        if (coords.length >= 3) {
          setPlannedRoute(coords);
          setRouteSteps(route.legs[0].steps || []);
          setCurrentStepIndex(0);
          lastSpokenRef.current = { index: -1, milestone: null };
          setError(null);
          setIsRerouting(false);
        }
      }
    } catch (e) {
      console.error("Erro OSRM:", e);
      setError("Erro ao conectar com servidor de rotas.");
    } finally {
      setIsCalculatingRoute(false);
      fetchInProgressRef.current = false;
    }
  };

  // GPS de ciclo único (não reinicia com mudanças de estado)
  useEffect(() => {
    if (!("geolocation" in navigator)) {
      setError("GPS não suportado neste navegador.");
      return;
    }

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { role, isActive, plannedRoute, routeSteps, currentStepIndex, isCalculating, destination, tripCode } = navDataRef.current;

        const newPoint: GeoPoint = {
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          timestamp: Date.now()
        };

        setUserPos(newPoint);

        // Somente processa se estiver em uma função ou configurando
        if (role === UserRole.NONE && !isConfiguringTrip) return;

        // Gravação do rastro do Mestre
        if (role === UserRole.MESTRE && isActive && tripCode) {
          const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
          if (distanceMoved > 10) {
            storageService.updateTripPath(tripCode, newPoint);
            lastRecordedPosRef.current = newPoint;
          }
        }

        // Recálculo automático (Mestre fora da rota)
        if (role === UserRole.MESTRE && isActive && plannedRoute.length > 0 && !isCalculating && destination) {
          if (!isPointNearRoute(newPoint, plannedRoute, 120)) {
            setIsRerouting(true);
            fetchRoadRoute(newPoint, destination);
          }
        }

        // Navegação por Voz
        if (isActive && routeSteps.length > 0) {
          const nextStep = routeSteps[currentStepIndex];
          if (nextStep) {
            const stepPos = { lat: nextStep.maneuver.location[1], lng: nextStep.maneuver.location[0] };
            const distToStep = calculateDistance(newPoint, stepPos);

            if (distToStep <= 250 && distToStep > 60) {
              if (lastSpokenRef.current.index !== currentStepIndex || lastSpokenRef.current.milestone !== 'far') {
                speak(`Em 250 metros, ${nextStep.maneuver.instruction}`);
                lastSpokenRef.current = { index: currentStepIndex, milestone: 'far' };
              }
            }

            if (distToStep <= 45) {
              if (lastSpokenRef.current.milestone !== 'near') {
                speak(nextStep.maneuver.instruction);
                lastSpokenRef.current = { index: currentStepIndex, milestone: 'near' };
                if (currentStepIndex < routeSteps.length - 1) {
                  setCurrentStepIndex(prev => prev + 1);
                }
              }
            }
          }
        }
      },
      (err) => {
        console.error(err);
        setError("Perda de sinal de GPS.");
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );

    return () => {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
    };
  }, [isConfiguringTrip]); // Somente reinicia se entrar/sair da configuração, não por cada metro andado

  // Sincronização Seguidor
  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip({...trip});
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
          if (trip.plannedRoute) setPlannedRoute(trip.plannedRoute);
        }
      }, 4000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  // Busca Gemini
  useEffect(() => {
    if (selectedDest && searchQuery === selectedDest.name) return;
    if (searchQuery.length < 3) { setSuggestions([]); return; }
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `Busque 5 locais reais para: "${searchQuery}". Local: ${userPos?.lat}, ${userPos?.lng}. JSON com name, address, lat, lng.`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  lat: { type: Type.NUMBER },
                  lng: { type: Type.NUMBER },
                  name: { type: Type.STRING },
                  address: { type: Type.STRING }
                },
                required: ["lat", "lng", "name", "address"]
              }
            }
          }
        });
        if (response?.text) setSuggestions(JSON.parse(response.text));
      } catch (err) { console.error(err); } finally { setIsSearching(false); }
    }, 1000);
  }, [searchQuery]);

  // Cálculo inicial de rota quando destino é selecionado
  useEffect(() => {
    if (selectedDest && userPos && !plannedRoute.length && !isCalculatingRoute) {
      fetchRoadRoute(userPos, selectedDest);
    }
  }, [selectedDest, userPos]);

  const handleStartTrip = () => {
    if (!selectedDest || plannedRoute.length < 3) return;
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: `Comboio para ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(false);
    speak("Viagem iniciada. Siga o caminho destacado.");
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center">
          <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <Navigation size={48} className="text-white" />
          </div>
          <h1 className="text-5xl font-black mb-3 tracking-tighter">Siga o Mestre</h1>
          <p className="text-slate-400 text-lg">Seu comboio inteligente.</p>
        </div>
        <div className="w-full max-w-sm space-y-5">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 text-white font-bold py-6 px-6 rounded-3xl flex items-center justify-between shadow-xl active:scale-95 transition-all">
            <div className="flex items-center"><Play size={28} className="mr-4 fill-white"/> Criar Comboio</div>
            <ChevronUp className="rotate-90 opacity-40" />
          </button>
          <div className="relative py-4"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div><div className="relative flex justify-center text-xs text-slate-500 uppercase font-black"><span className="bg-[#0f172a] px-4">Entrar em Grupo</span></div></div>
          <div className="space-y-3">
            <input type="text" placeholder="CÓDIGO" className="w-full bg-slate-800 border-2 border-slate-700 rounded-2xl px-5 py-5 text-white uppercase text-center text-2xl font-mono font-black tracking-widest outline-none focus:border-blue-500 transition-all" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
            <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); setPlannedRoute(trip.plannedRoute || []); setIsBottomSheetOpen(false); }else{ setError("Código inválido."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-black py-5 px-6 rounded-2xl flex items-center justify-center active:scale-95 transition-all shadow-xl">
              <Users size={24} className="mr-3" /> Entrar como Seguidor
            </button>
          </div>
          {error && <div className="text-red-400 text-sm font-bold bg-red-500/10 p-3 rounded-xl border border-red-500/20 text-center">{error}</div>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white overflow-hidden z-[2000]">
        <div className="relative h-16 bg-slate-900 text-white flex items-center px-4 shrink-0 z-50">
          <button onClick={() => setIsConfiguringTrip(false)} className="flex items-center text-slate-400 font-bold"><ArrowLeft className="mr-2" size={20} /> Voltar</button>
          <div className="flex-1 text-center font-black">Destino do Comboio</div>
          <div className="w-10"></div>
        </div>
        <div className="flex-grow relative w-full overflow-hidden">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => { setSelectedDest({ lat, lng, name: "Ponto no Mapa", address: "Localização personalizada" }); setPlannedRoute([]); }}
            isSelectingDestination={true}
          />
          <div className="absolute top-4 left-4 right-4 z-[3000]">
            <div className="relative flex shadow-xl bg-white rounded-2xl overflow-hidden border border-slate-100">
              <div className="flex items-center pl-4 text-slate-400">{isSearching ? <Loader2 size={24} className="animate-spin text-blue-500" /> : <Search size={24} />}</div>
              <input type="text" placeholder="Para onde o grupo vai?" className="w-full px-4 py-5 border-none focus:ring-0 text-slate-900 font-bold" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
            </div>
            {suggestions.length > 0 && !selectedDest && (
              <div className="mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden max-h-[50vh] overflow-y-auto">
                {suggestions.map((item, idx) => (
                  <button key={idx} onClick={() => { setSelectedDest(item); setSearchQuery(item.name); setSuggestions([]); setPlannedRoute([]); }} className="w-full px-5 py-4 flex items-start space-x-4 hover:bg-blue-50 border-b border-slate-50 last:border-b-0 text-left">
                    <MapPin size={20} className="text-slate-400 mt-1" />
                    <div className="flex-1 truncate">
                      <div className="font-bold text-slate-900 truncate">{item.name}</div>
                      <div className="text-sm text-slate-400 truncate">{item.address}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
          {selectedDest && (
            <div className="absolute bottom-8 left-4 right-4 z-[2000] bg-white p-6 rounded-[2.5rem] shadow-2xl border border-slate-100 animate-in slide-in-from-bottom">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-50 p-4 rounded-2xl shrink-0 flex items-center justify-center">
                  {isCalculatingRoute ? <Loader2 className="text-blue-600 animate-spin" size={32} /> : <MapPin className="text-blue-600" size={32} />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">{isCalculatingRoute ? 'Traçando Caminho...' : 'Confirmar Destino'}</div>
                  <div className="text-slate-900 font-black text-2xl truncate">{selectedDest.name}</div>
                </div>
              </div>
              <button onClick={handleStartTrip} disabled={isCalculatingRoute || plannedRoute.length < 3} className={`w-full text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl ${isCalculatingRoute || plannedRoute.length < 3 ? 'bg-slate-300' : 'bg-blue-600 shadow-blue-500/40'}`}>
                {isCalculatingRoute ? 'Calculando Rota...' : 'Iniciar Comboio'}
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 w-full h-full overflow-hidden bg-slate-900">
      <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />
      <div className="absolute top-4 left-4 right-4 z-[500] flex flex-col space-y-3 pointer-events-none">
        <div className="bg-white/95 backdrop-blur-xl rounded-[2rem] p-4 shadow-2xl flex items-center justify-between border border-white pointer-events-auto">
          <div className="flex items-center space-x-4">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg text-2xl`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-black text-slate-900 text-lg leading-tight">{role === UserRole.MESTRE ? 'Mestre' : 'Seguindo Mestre'}</h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1"><div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div> AO VIVO</div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <button onClick={() => setIsVoiceEnabled(!isVoiceEnabled)} className={`p-3.5 rounded-2xl transition-all ${isVoiceEnabled ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
               {isVoiceEnabled ? <Volume2 size={24} /> : <VolumeX size={24} />}
             </button>
             <button onClick={() => { if(window.confirm("Sair do comboio?")) { setRole(UserRole.NONE); setCurrentTrip(null); } }} className="p-3.5 text-slate-400 hover:text-red-500 bg-slate-50 rounded-2xl shadow-inner active:scale-90 transition-all border border-slate-100">
               <LogOut size={24} />
             </button>
          </div>
        </div>
        {currentTrip?.isActive && routeSteps[currentStepIndex] && (
          <div className="bg-blue-600 text-white p-5 rounded-[2rem] shadow-2xl border-b-8 border-blue-800 animate-in slide-in-from-top duration-500 pointer-events-auto">
            <div className="flex items-center space-x-5">
               <div className="bg-white/20 p-3 rounded-2xl"><Navigation size={32} className="rotate-45" /></div>
               <div className="flex-1">
                  <div className="text-[10px] font-black text-blue-100 uppercase tracking-widest mb-1">Próxima Instrução</div>
                  <div className="font-black text-xl leading-tight">{routeSteps[currentStepIndex].maneuver.instruction}</div>
               </div>
            </div>
          </div>
        )}
        {isRerouting && <div className="self-center bg-amber-500 text-white px-6 py-2 rounded-full font-black text-xs uppercase tracking-widest shadow-lg animate-pulse border-2 border-white">Recalculando...</div>}
      </div>
      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-2xl rounded-t-[3rem] z-[1000] transition-all duration-700 ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-90px)]'}`}>
        <div className="w-full flex flex-col items-center py-5 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-16 h-1.5 bg-slate-200 rounded-full mb-2"></div>
          {!isBottomSheetOpen && <div className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] py-2">Info Viagem</div>}
          {isBottomSheetOpen && <ChevronDown size={24} className="text-slate-300" />}
        </div>
        <div className="px-8 pb-12 space-y-6">
          <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between">
            <div className="flex-1">
               <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Código do Grupo</div>
               <div className="text-4xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="p-5 bg-white rounded-2xl shadow-md text-blue-600 active:scale-90 transition-all border border-slate-50">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
            </button>
          </div>
          {currentTrip?.destination && (
            <div className="flex items-center space-x-5 text-slate-600 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
              <div className="bg-blue-100 p-3 rounded-xl"><MapPin size={28} className="text-blue-600" /></div>
              <div className="flex-1 truncate">
                <div className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-0.5">Destino</div>
                <div className="font-black text-xl text-slate-800 truncate">{currentTrip.destination.name}</div>
              </div>
            </div>
          )}
          <div className="grid grid-cols-1 gap-4 pt-2">
            {role === UserRole.MESTRE && (
              <button onClick={() => { if(window.confirm("Encerrar viagem?")) { if(currentTrip) storageService.saveTrip({...currentTrip, isActive: false}); setCurrentTrip(null); setRole(UserRole.NONE); } }} className="w-full bg-red-500 text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl">Encerrar Viagem</button>
            )}
            <button onClick={() => window.open(`https://wa.me/?text=Entre no meu comboio Siga o Mestre! Código: ${currentTrip?.code}`, '_blank')} className="w-full border-2 border-slate-100 py-5 rounded-3xl font-black text-slate-600 flex items-center justify-center hover:bg-slate-50 transition-colors">
              <Share2 className="mr-3" size={24} /> Compartilhar Código
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, Share2, Users, MapPin, ChevronUp, Copy, Check, LogOut, Search, Loader2, ArrowLeft, Volume2, VolumeX, ChevronDown, AlertCircle, RefreshCw, X } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint | {lat: number, lng: number}, p2: GeoPoint | {lat: number, lng: number}) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const isPointNearRoute = (point: GeoPoint, route: [number, number][], thresholdMeters = 100) => {
  if (!route || route.length < 2) return true;
  for (let i = 0; i < route.length; i += Math.max(1, Math.floor(route.length / 12))) {
    const dist = calculateDistance(point, { lat: route[i][0], lng: route[i][1] });
    if (dist < thresholdMeters) return true;
  }
  return false;
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [suggestions, setSuggestions] = useState<Destination[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [routeSteps, setRouteSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [isRerouting, setIsRerouting] = useState(false);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fetchControllerRef = useRef<AbortController | null>(null);

  const navDataRef = useRef({
    role,
    isActive: false,
    plannedRoute: [] as [number, number][],
    routeSteps: [] as any[],
    currentStepIndex: 0,
    isCalculating: false,
    destination: null as Destination | null,
    tripCode: '',
    isConfiguring: false
  });

  useEffect(() => {
    navDataRef.current = {
      role,
      isActive: currentTrip?.isActive || false,
      plannedRoute,
      routeSteps,
      currentStepIndex,
      isCalculating: isCalculatingRoute,
      destination: selectedDest || currentTrip?.destination || null,
      tripCode: currentTrip?.code || '',
      isConfiguring: isConfiguringTrip
    };
  }, [role, currentTrip, plannedRoute, routeSteps, currentStepIndex, isCalculatingRoute, selectedDest, isConfiguringTrip]);

  const lastSpokenRef = useRef({ index: -1, milestone: null as string | null });

  const speak = useCallback((text: string) => {
    if (!isVoiceEnabled) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  }, [isVoiceEnabled]);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    if (fetchControllerRef.current) fetchControllerRef.current.abort();
    fetchControllerRef.current = new AbortController();

    setIsCalculatingRoute(true);
    setError(null);

    const timeoutId = setTimeout(() => {
      if (fetchControllerRef.current) fetchControllerRef.current.abort();
      setError("O servidor de rotas demorou muito. Verifique sua internet.");
      setIsCalculatingRoute(false);
    }, 12000); // 12 segundos de limite

    try {
      const response = await fetch(
        `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true&language=pt`,
        { signal: fetchControllerRef.current.signal }
      );

      const data = await response.json();
      clearTimeout(timeoutId);

      if (data.routes && data.routes.length > 0) {
        const route = data.routes[0];
        const coords: [number, number][] = route.geometry.coordinates.map((c: any) => [c[1], c[0]]);

        if (coords.length >= 3) {
          setPlannedRoute(coords);
          setRouteSteps(route.legs[0].steps || []);
          setCurrentStepIndex(0);
          lastSpokenRef.current = { index: -1, milestone: null };
          setError(null);
          setIsRerouting(false);
          if (isRerouting) speak("Rota recalculada.");
        } else {
          setError("Não foi possível traçar um caminho pelas ruas neste local.");
        }
      } else {
        setError("Nenhuma rota encontrada para este destino.");
      }
    } catch (e: any) {
      if (e.name !== 'AbortError') {
        console.error("Erro OSRM:", e);
        setError("Falha ao calcular rota. Tente um local diferente.");
      }
    } finally {
      setIsCalculatingRoute(false);
      fetchControllerRef.current = null;
    }
  };

  // GPS FIXO: Inicia uma vez e mantém conectado para evitar "piscadas" e lags de hardware
  useEffect(() => {
    if (!("geolocation" in navigator)) {
      setError("GPS não disponível.");
      return;
    }

    // Função de watch única e persistente
    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { role, isActive, plannedRoute, routeSteps, currentStepIndex, isCalculating, destination, tripCode, isConfiguring } = navDataRef.current;

        const newPoint: GeoPoint = {
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          timestamp: Date.now()
        };

        setUserPos(newPoint);

        // Se estiver apenas navegando no menu inicial, não faz lógica pesada
        if (role === UserRole.NONE && !isConfiguring) return;

        // Atualização de trilha do Mestre
        if (role === UserRole.MESTRE && isActive && tripCode) {
          const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
          if (distanceMoved > 12) {
            storageService.updateTripPath(tripCode, newPoint);
            lastRecordedPosRef.current = newPoint;
          }
        }

        // Recálculo (apenas se estiver longe da rota e não estiver já calculando)
        if (role === UserRole.MESTRE && isActive && plannedRoute.length > 10 && !isCalculating && destination) {
          if (!isPointNearRoute(newPoint, plannedRoute, 130)) {
            setIsRerouting(true);
            fetchRoadRoute(newPoint, destination);
          }
        }

        // Instruções por voz
        if (isActive && routeSteps.length > 0) {
          const nextStep = routeSteps[currentStepIndex];
          if (nextStep) {
            const stepPos = { lat: nextStep.maneuver.location[1], lng: nextStep.maneuver.location[0] };
            const distToStep = calculateDistance(newPoint, stepPos);

            if (distToStep <= 200 && distToStep > 50) {
              if (lastSpokenRef.current.index !== currentStepIndex || lastSpokenRef.current.milestone !== 'far') {
                speak(`Em 200 metros, ${nextStep.maneuver.instruction}`);
                lastSpokenRef.current = { index: currentStepIndex, milestone: 'far' };
              }
            }

            if (distToStep <= 40) {
              if (lastSpokenRef.current.milestone !== 'near') {
                speak(nextStep.maneuver.instruction);
                lastSpokenRef.current = { index: currentStepIndex, milestone: 'near' };
                if (currentStepIndex < routeSteps.length - 1) {
                  setCurrentStepIndex(prev => prev + 1);
                }
              }
            }
          }
        }
      },
      (err) => {
        console.warn("GPS Signal Loss:", err);
        // Não resetamos o erro aqui para não piscar a tela, apenas logamos
      },
      { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }
    );

    return () => {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
    };
  }, []); // Efeito sem dependências para rodar UMA VEZ

  // Sincronização Seguidor
  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip({...trip});
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
          if (trip.plannedRoute) setPlannedRoute(trip.plannedRoute);
        }
      }, 5000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  // Busca Local Gemini
  useEffect(() => {
    if (selectedDest && searchQuery === selectedDest.name) return;
    if (searchQuery.length < 3) { setSuggestions([]); return; }
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `Busque 5 locais reais para: "${searchQuery}". Local atual: ${userPos?.lat}, ${userPos?.lng}. Retorne JSON com name, address, lat, lng.`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  lat: { type: Type.NUMBER },
                  lng: { type: Type.NUMBER },
                  name: { type: Type.STRING },
                  address: { type: Type.STRING }
                },
                required: ["lat", "lng", "name", "address"]
              }
            }
          }
        });
        if (response?.text) setSuggestions(JSON.parse(response.text));
      } catch (err) { console.error(err); } finally { setIsSearching(false); }
    }, 1200);
  }, [searchQuery]);

  // Disparo automático de rota ao escolher destino
  useEffect(() => {
    if (selectedDest && userPos && !plannedRoute.length && !isCalculatingRoute && isConfiguringTrip) {
      fetchRoadRoute(userPos, selectedDest);
    }
  }, [selectedDest, userPos, isConfiguringTrip]);

  const handleStartTrip = () => {
    if (!selectedDest || plannedRoute.length < 3) return;
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: `Comboio para ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(false);
    speak("Comboio iniciado. Dirija com cuidado.");
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center animate-in fade-in zoom-in duration-700">
          <div className="bg-blue-600 w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-[0_0_50px_rgba(37,99,235,0.4)]">
            <Navigation size={48} className="text-white" />
          </div>
          <h1 className="text-5xl font-black mb-3 tracking-tighter">Siga o Mestre</h1>
          <p className="text-slate-400 text-lg">Seu comboio, sua rota.</p>
        </div>
        <div className="w-full max-w-sm space-y-5">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 text-white font-bold py-6 px-6 rounded-3xl flex items-center justify-between shadow-xl active:scale-95 transition-all">
            <div className="flex items-center"><Play size={28} className="mr-4 fill-white"/> Criar Novo Comboio</div>
            <ChevronUp className="rotate-90 opacity-40" />
          </button>
          <div className="relative py-4"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div><div className="relative flex justify-center text-xs text-slate-500 uppercase font-black"><span className="bg-[#0f172a] px-4">Entrar em Grupo Existente</span></div></div>
          <div className="space-y-3">
            <input type="text" placeholder="CÓDIGO DE 6 DÍGITOS" className="w-full bg-slate-800 border-2 border-slate-700 rounded-2xl px-5 py-5 text-white uppercase text-center text-2xl font-mono font-black tracking-widest outline-none focus:border-blue-500 transition-all placeholder:text-slate-600" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
            <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); setPlannedRoute(trip.plannedRoute || []); setIsBottomSheetOpen(false); }else{ setError("Código inválido ou não encontrado."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-black py-5 px-6 rounded-2xl flex items-center justify-center active:scale-95 transition-all shadow-xl">
              <Users size={24} className="mr-3" /> Entrar como Seguidor
            </button>
          </div>
          {error && (
            <div className="flex items-center justify-center space-x-2 text-red-400 text-sm font-bold bg-red-500/10 p-4 rounded-2xl border border-red-500/20">
              <AlertCircle size={18} />
              <span>{error}</span>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white overflow-hidden z-[2000]">
        <div className="relative h-16 bg-slate-900 text-white flex items-center px-4 shrink-0 z-50">
          <button onClick={() => { setIsConfiguringTrip(false); setSelectedDest(null); setPlannedRoute([]); }} className="flex items-center text-slate-400 font-bold"><ArrowLeft className="mr-2" size={20} /> Cancelar</button>
          <div className="flex-1 text-center font-black">Configurar Destino</div>
          <div className="w-10"></div>
        </div>
        <div className="flex-grow relative w-full overflow-hidden">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => { setSelectedDest({ lat, lng, name: "Local Escolhido", address: "Marcado no mapa" }); setPlannedRoute([]); }}
            isSelectingDestination={true}
          />
          <div className="absolute top-4 left-4 right-4 z-[3000]">
            <div className="relative flex shadow-2xl bg-white rounded-[1.5rem] overflow-hidden border border-slate-100 p-1">
              <div className="flex items-center pl-4 text-slate-400">{isSearching ? <Loader2 size={24} className="animate-spin text-blue-500" /> : <Search size={24} />}</div>
              <input type="text" placeholder="Pesquisar endereço ou local..." className="w-full px-4 py-5 border-none focus:ring-0 text-slate-900 font-bold placeholder:text-slate-300" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              {searchQuery && (
                <button onClick={() => { setSearchQuery(''); setSuggestions([]); }} className="p-4 text-slate-300"><X size={20}/></button>
              )}
            </div>
            {suggestions.length > 0 && !selectedDest && (
              <div className="mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden max-h-[50vh] overflow-y-auto animate-in fade-in slide-in-from-top-2">
                {suggestions.map((item, idx) => (
                  <button key={idx} onClick={() => { setSelectedDest(item); setSearchQuery(item.name); setSuggestions([]); setPlannedRoute([]); }} className="w-full px-5 py-4 flex items-start space-x-4 hover:bg-blue-50 border-b border-slate-50 last:border-b-0 text-left transition-colors">
                    <div className="bg-slate-100 p-2 rounded-lg mt-1"><MapPin size={18} className="text-slate-500" /></div>
                    <div className="flex-1 truncate">
                      <div className="font-bold text-slate-900 truncate">{item.name}</div>
                      <div className="text-sm text-slate-400 truncate">{item.address}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {selectedDest && (
            <div className="absolute bottom-8 left-4 right-4 z-[2000] bg-white p-6 rounded-[2.5rem] shadow-[0_20px_60px_rgba(0,0,0,0.15)] border border-slate-50 animate-in slide-in-from-bottom duration-500">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-600 p-4 rounded-2xl shrink-0 flex items-center justify-center text-white shadow-lg">
                  {isCalculatingRoute ? <Loader2 className="animate-spin" size={32} /> : <MapPin size={32} />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-1">{isCalculatingRoute ? 'Conectando ao servidor...' : 'Destino Selecionado'}</div>
                  <div className="text-slate-900 font-black text-2xl truncate leading-tight">{selectedDest.name}</div>
                </div>
              </div>

              {error ? (
                <div className="mb-6 p-4 bg-red-50 rounded-2xl border border-red-100 flex items-center space-x-3 text-red-600">
                  <AlertCircle className="shrink-0" />
                  <p className="text-sm font-bold leading-tight">{error}</p>
                  <button onClick={() => userPos && fetchRoadRoute(userPos, selectedDest)} className="bg-red-600 text-white p-2 rounded-lg"><RefreshCw size={20}/></button>
                </div>
              ) : null}

              <button onClick={handleStartTrip} disabled={isCalculatingRoute || plannedRoute.length < 3} className={`w-full text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl flex items-center justify-center space-x-3 ${isCalculatingRoute || plannedRoute.length < 3 ? 'bg-slate-200 text-slate-400' : 'bg-blue-600 shadow-blue-500/40'}`}>
                {isCalculatingRoute ? (
                  <>
                    <Loader2 className="animate-spin" size={24} />
                    <span>Processando Rota...</span>
                  </>
                ) : 'Iniciar Comboio'}
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 w-full h-full overflow-hidden bg-slate-900">
      <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />
      <div className="absolute top-4 left-4 right-4 z-[500] flex flex-col space-y-3 pointer-events-none">
        <div className="bg-white/95 backdrop-blur-xl rounded-[2rem] p-4 shadow-2xl flex items-center justify-between border border-white pointer-events-auto">
          <div className="flex items-center space-x-4">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg text-2xl`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-black text-slate-900 text-lg leading-tight">{role === UserRole.MESTRE ? 'Mestre' : 'Seguindo'}</h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1"><div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div> AO VIVO</div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <button onClick={() => setIsVoiceEnabled(!isVoiceEnabled)} className={`p-3.5 rounded-2xl transition-all ${isVoiceEnabled ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
               {isVoiceEnabled ? <Volume2 size={24} /> : <VolumeX size={24} />}
             </button>
             <button onClick={() => { if(window.confirm("Sair do comboio agora?")) { setRole(UserRole.NONE); setCurrentTrip(null); setPlannedRoute([]); } }} className="p-3.5 text-slate-400 hover:text-red-500 bg-slate-50 rounded-2xl shadow-inner active:scale-90 transition-all border border-slate-100">
               <LogOut size={24} />
             </button>
          </div>
        </div>
        {currentTrip?.isActive && routeSteps[currentStepIndex] && (
          <div className="bg-blue-600 text-white p-5 rounded-[2rem] shadow-2xl border-b-8 border-blue-800 animate-in slide-in-from-top duration-500 pointer-events-auto">
            <div className="flex items-center space-x-5">
               <div className="bg-white/20 p-3 rounded-2xl"><Navigation size={32} className="rotate-45" /></div>
               <div className="flex-1">
                  <div className="text-[10px] font-black text-blue-100 uppercase tracking-[0.2em] mb-1">Navegação</div>
                  <div className="font-black text-xl leading-tight">{routeSteps[currentStepIndex].maneuver.instruction}</div>
               </div>
            </div>
          </div>
        )}
        {isRerouting && <div className="self-center bg-amber-500 text-white px-6 py-2 rounded-full font-black text-xs uppercase tracking-widest shadow-lg animate-pulse border-2 border-white pointer-events-none">Recalculando Caminho...</div>}
      </div>
      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-2xl rounded-t-[3rem] z-[1000] transition-all duration-700 ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-90px)]'}`}>
        <div className="w-full flex flex-col items-center py-5 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-16 h-1.5 bg-slate-200 rounded-full mb-2"></div>
          {!isBottomSheetOpen && <div className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] py-2">Informações do Grupo</div>}
          {isBottomSheetOpen && <ChevronDown size={24} className="text-slate-300" />}
        </div>
        <div className="px-8 pb-12 space-y-6">
          <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between">
            <div className="flex-1">
               <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Código Compartilhável</div>
               <div className="text-4xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="p-5 bg-white rounded-2xl shadow-md text-blue-600 active:scale-90 transition-all border border-slate-50">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
            </button>
          </div>
          {currentTrip?.destination && (
            <div className="flex items-center space-x-5 text-slate-600 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
              <div className="bg-blue-100 p-3 rounded-xl"><MapPin size={28} className="text-blue-600" /></div>
              <div className="flex-1 truncate">
                <div className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-0.5">Destino</div>
                <div className="font-black text-xl text-slate-800 truncate">{currentTrip.destination.name}</div>
              </div>
            </div>
          )}
          <div className="grid grid-cols-1 gap-4 pt-2">
            {role === UserRole.MESTRE && (
              <button onClick={() => { if(window.confirm("Finalizar comboio para todos?")) { if(currentTrip) storageService.saveTrip({...currentTrip, isActive: false}); setCurrentTrip(null); setRole(UserRole.NONE); setPlannedRoute([]); } }} className="w-full bg-red-500 text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl">Finalizar Comboio</button>
            )}
            <button onClick={() => window.open(`https://wa.me/?text=Siga meu comboio no app Siga o Mestre! Use o código: ${currentTrip?.code}`, '_blank')} className="w-full border-2 border-slate-100 py-5 rounded-3xl font-black text-slate-600 flex items-center justify-center hover:bg-slate-50 transition-colors shadow-sm">
              <Share2 className="mr-3" size={24} /> Compartilhar Via WhatsApp
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, Share2, Users, MapPin, ChevronUp, Copy, Check, LogOut, Search, Loader2, ArrowLeft, Volume2, VolumeX, ChevronDown, AlertCircle, RefreshCw, X } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint | {lat: number, lng: number}, p2: GeoPoint | {lat: number, lng: number}) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const isPointNearRoute = (point: GeoPoint, route: [number, number][], thresholdMeters = 100) => {
  if (!route || route.length < 2) return true;
  for (let i = 0; i < route.length; i += Math.max(1, Math.floor(route.length / 12))) {
    const dist = calculateDistance(point, { lat: route[i][0], lng: route[i][1] });
    if (dist < thresholdMeters) return true;
  }
  return false;
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [suggestions, setSuggestions] = useState<Destination[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [routeLoadingStatus, setRouteLoadingStatus] = useState('');
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [routeSteps, setRouteSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [isRerouting, setIsRerouting] = useState(false);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fetchControllerRef = useRef<AbortController | null>(null);
  const isCurrentlyFetchingRef = useRef<boolean>(false);

  const navDataRef = useRef({
    role,
    isActive: false,
    plannedRoute: [] as [number, number][],
    routeSteps: [] as any[],
    currentStepIndex: 0,
    isCalculating: false,
    destination: null as Destination | null,
    tripCode: '',
    isConfiguring: false
  });

  useEffect(() => {
    navDataRef.current = {
      role,
      isActive: currentTrip?.isActive || false,
      plannedRoute,
      routeSteps,
      currentStepIndex,
      isCalculating: isCalculatingRoute,
      destination: selectedDest || currentTrip?.destination || null,
      tripCode: currentTrip?.code || '',
      isConfiguring: isConfiguringTrip
    };
  }, [role, currentTrip, plannedRoute, routeSteps, currentStepIndex, isCalculatingRoute, selectedDest, isConfiguringTrip]);

  const lastSpokenRef = useRef({ index: -1, milestone: null as string | null });

  const speak = useCallback((text: string) => {
    if (!isVoiceEnabled) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  }, [isVoiceEnabled]);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    // Se já estiver buscando, ignora novos pedidos para evitar cancelar o anterior
    if (isCurrentlyFetchingRef.current) return;

    isCurrentlyFetchingRef.current = true;
    setIsCalculatingRoute(true);
    setRouteLoadingStatus('Iniciando conexão...');
    setError(null);

    if (fetchControllerRef.current) fetchControllerRef.current.abort();
    fetchControllerRef.current = new AbortController();

    const timeoutId = setTimeout(() => {
      if (fetchControllerRef.current) fetchControllerRef.current.abort();
      setError("O servidor demorou muito. Verifique sua conexão.");
      setIsCalculatingRoute(false);
      isCurrentlyFetchingRef.current = false;
    }, 15000);

    try {
      setRouteLoadingStatus('Traçando ruas...');
      // Usando o servidor principal com fallback manual caso precise
      const url = `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true&language=pt`;

      const response = await fetch(url, { signal: fetchControllerRef.current.signal });

      if (!response.ok) throw new Error("Falha no servidor de rotas");

      setRouteLoadingStatus('Processando mapa...');
      const data = await response.json();
      clearTimeout(timeoutId);

      if (data.routes && data.routes.length > 0) {
        const route = data.routes[0];
        const coords: [number, number][] = route.geometry.coordinates.map((c: any) => [c[1], c[0]]);

        if (coords.length >= 2) {
          setPlannedRoute(coords);
          setRouteSteps(route.legs[0].steps || []);
          setCurrentStepIndex(0);
          lastSpokenRef.current = { index: -1, milestone: null };
          setError(null);
          setIsRerouting(false);
          if (isRerouting) speak("Rota atualizada.");
        }
      } else {
        setError("Nenhuma rua encontrada até esse destino.");
      }
    } catch (e: any) {
      if (e.name !== 'AbortError') {
        console.error("Erro OSRM:", e);
        setError("Não foi possível calcular via ruas. Tente outro ponto.");
      }
    } finally {
      setIsCalculatingRoute(false);
      isCurrentlyFetchingRef.current = false;
      fetchControllerRef.current = null;
    }
  };

  // GPS PERSISTENTE: Nunca reinicia, evita o "piscado"
  useEffect(() => {
    if (!("geolocation" in navigator)) {
      setError("GPS não disponível.");
      return;
    }

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { role, isActive, plannedRoute, routeSteps, currentStepIndex, isCalculating, destination, tripCode, isConfiguring } = navDataRef.current;

        const newPoint: GeoPoint = {
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          timestamp: Date.now()
        };

        setUserPos(newPoint);

        if (role === UserRole.NONE && !isConfiguring) return;

        // Registro de trilha do Mestre
        if (role === UserRole.MESTRE && isActive && tripCode) {
          const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
          if (distanceMoved > 15) {
            storageService.updateTripPath(tripCode, newPoint);
            lastRecordedPosRef.current = newPoint;
          }
        }

        // Recálculo automático de rota (Mestre fora da rota)
        if (role === UserRole.MESTRE && isActive && plannedRoute.length > 5 && !isCalculating && destination) {
          const distToRoute = !isPointNearRoute(newPoint, plannedRoute, 150);
          if (distToRoute) {
            // Pequeno delay para ter certeza que não é erro momentâneo do GPS
            if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
            debounceTimerRef.current = setTimeout(() => {
                setIsRerouting(true);
                fetchRoadRoute(newPoint, destination);
            }, 2000);
          }
        }

        // Voz e Manobras
        if (isActive && routeSteps.length > 0) {
          const nextStep = routeSteps[currentStepIndex];
          if (nextStep) {
            const stepPos = { lat: nextStep.maneuver.location[1], lng: nextStep.maneuver.location[0] };
            const distToStep = calculateDistance(newPoint, stepPos);

            if (distToStep <= 250 && distToStep > 60 && lastSpokenRef.current.milestone !== 'far') {
                speak(`Em 250 metros, ${nextStep.maneuver.instruction}`);
                lastSpokenRef.current = { index: currentStepIndex, milestone: 'far' };
            }

            if (distToStep <= 45 && lastSpokenRef.current.milestone !== 'near') {
                speak(nextStep.maneuver.instruction);
                lastSpokenRef.current = { index: currentStepIndex, milestone: 'near' };
                if (currentStepIndex < routeSteps.length - 1) {
                  setCurrentStepIndex(prev => prev + 1);
                }
            }
          }
        }
      },
      (err) => console.warn("GPS Signal Issue:", err),
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );

    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, []);

  // Busca de Locais (Gemini)
  useEffect(() => {
    if (selectedDest && searchQuery === selectedDest.name) return;
    if (searchQuery.length < 3) { setSuggestions([]); return; }
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `Busque 5 locais para: "${searchQuery}" perto de ${userPos?.lat}, ${userPos?.lng}. JSON com name, address, lat, lng.`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  lat: { type: Type.NUMBER },
                  lng: { type: Type.NUMBER },
                  name: { type: Type.STRING },
                  address: { type: Type.STRING }
                },
                required: ["lat", "lng", "name", "address"]
              }
            }
          }
        });
        if (response?.text) setSuggestions(JSON.parse(response.text));
      } catch (err) { console.error(err); } finally { setIsSearching(false); }
    }, 1000);
  }, [searchQuery]);

  // Cálculo de rota inicial - APENAS UMA VEZ ao selecionar
  useEffect(() => {
    if (selectedDest && userPos && !plannedRoute.length && !isCalculatingRoute && isConfiguringTrip) {
      fetchRoadRoute(userPos, selectedDest);
    }
  }, [selectedDest, isConfiguringTrip]); // Removido userPos das dependências para não cancelar o fetch se o GPS mexer

  const handleStartTrip = () => {
    if (!selectedDest || plannedRoute.length < 2) return;
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: `Comboio para ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(false);
    speak("Comboio iniciado.");
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center">
