               <div className="bg-white/20 p-3 rounded-2xl"><Navigation size={32} className="rotate-45" /></div>
               <div className="flex-1">
                  <div className="text-[10px] font-black text-blue-100 uppercase tracking-widest mb-1">Próxima Manobra</div>
                  <div className="font-black text-xl leading-tight">{routeSteps[currentStepIndex].maneuver.instruction}</div>
