      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-2xl rounded-t-[3rem] z-[1000] transition-all duration-700 ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-90px)]'}`}>
        <div className="w-full flex flex-col items-center py-5 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-16 h-1.5 bg-slate-200 rounded-full mb-2"></div>
