        <div className="px-8 pb-12 space-y-6">
          <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between">
            <div className="flex-1">
               <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Código do Grupo</div>
               <div className="text-4xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="p-5 bg-white rounded-2xl shadow-md text-blue-600 active:scale-90 transition-all">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
            </button>
          </div>
          <div className="grid grid-cols-1 gap-4 pt-2">
            {role === UserRole.MESTRE && (
              <button onClick={() => { if(window.confirm("Encerrar comboio?")) { if(currentTrip) storageService.saveTrip({...currentTrip, isActive: false}); setCurrentTrip(null); setRole(UserRole.NONE); } }} className="w-full bg-red-500 text-white font-black py-6 rounded-3xl shadow-xl active:scale-95 transition-all text-xl">Encerrar Viagem</button>
            )}
            <button onClick={() => window.open(`https://wa.me/?text=Entre no meu comboio Siga o Mestre! Código: ${currentTrip?.code}`, '_blank')} className="w-full border-2 border-slate-100 py-5 rounded-3xl font-black text-slate-600 flex items-center justify-center hover:bg-slate-50 transition-colors">
              <Share2 className="mr-3" size={24} /> Convidar Amigos
