import React, { useState, useEffect, useRef, useCallback } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, Share2, Users, MapPin, ChevronUp, Copy, Check, LogOut, Search, Loader2, ArrowLeft, Volume2, VolumeX, ChevronDown, AlertCircle, RefreshCw, X, Zap } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint | {lat: number, lng: number}, p2: GeoPoint | {lat: number, lng: number}) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const isPointNearRoute = (point: GeoPoint, route: [number, number][], thresholdMeters = 150) => {
  if (!route || route.length < 2) return true;
  // Checa apenas alguns pontos da rota para performance
  for (let i = 0; i < route.length; i += Math.max(1, Math.floor(route.length / 10))) {
    const dist = calculateDistance(point, { lat: route[i][0], lng: route[i][1] });
    if (dist < thresholdMeters) return true;
  }
  return false;
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [suggestions, setSuggestions] = useState<Destination[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [routeLoadingStatus, setRouteLoadingStatus] = useState('');
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [routeSteps, setRouteSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(true);
  const [isRerouting, setIsRerouting] = useState(false);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fetchControllerRef = useRef<AbortController | null>(null);
  const lastFetchedIdRef = useRef<string>('');

  const navDataRef = useRef({
    role,
    isActive: false,
    plannedRoute: [] as [number, number][],
    routeSteps: [] as any[],
    currentStepIndex: 0,
    isCalculating: false,
    destination: null as Destination | null,
    tripCode: '',
    isConfiguring: false
  });

  useEffect(() => {
    navDataRef.current = {
      role,
      isActive: currentTrip?.isActive || false,
      plannedRoute,
      routeSteps,
      currentStepIndex,
      isCalculating: isCalculatingRoute,
      destination: selectedDest || currentTrip?.destination || null,
      tripCode: currentTrip?.code || '',
      isConfiguring: isConfiguringTrip
    };
  }, [role, currentTrip, plannedRoute, routeSteps, currentStepIndex, isCalculatingRoute, selectedDest, isConfiguringTrip]);

  const speak = useCallback((text: string) => {
    if (!isVoiceEnabled) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.0;
    window.speechSynthesis.speak(utterance);
  }, [isVoiceEnabled]);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    const fetchId = `${end.lat},${end.lng}`;
    if (fetchId === lastFetchedIdRef.current && isCalculatingRoute) return;

    // Aborta qualquer busca anterior que ainda esteja pendente
    if (fetchControllerRef.current) fetchControllerRef.current.abort();
    fetchControllerRef.current = new AbortController();

    lastFetchedIdRef.current = fetchId;
    setIsCalculatingRoute(true);
    setRouteLoadingStatus('Otimizando via ruas...');
    setError(null);

    // Fallback Imediato: Se não tiver rota, cria uma linha reta temporária para o usuário não ficar esperando
    if (plannedRoute.length === 0) {
      setPlannedRoute([[start.lat, start.lng], [end.lat, end.lng]]);
    }

    try {
      const url = `https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson&steps=true&language=pt`;

      const response = await fetch(url, { 
        signal: fetchControllerRef.current.signal,
        headers: { 'Accept': 'application/json' }
      });

      if (!response.ok) throw new Error("Servidor ocupado");

      const data = await response.json();

      if (data.routes && data.routes.length > 0) {
        const route = data.routes[0];
        const coords: [number, number][] = route.geometry.coordinates.map((c: any) => [c[1], c[0]]);

        if (coords.length >= 2) {
          setPlannedRoute(coords);
          setRouteSteps(route.legs[0].steps || []);
          setCurrentStepIndex(0);
          setError(null);
          setIsRerouting(false);
          if (isRerouting) speak("Rota recalculada com sucesso.");
        }
      }
    } catch (e: any) {
      if (e.name !== 'AbortError') {
        console.warn("OSRM Falhou, mantendo linha direta:", e);
        // Não mostramos erro fatal, apenas mantemos a rota de linha reta
        setRouteLoadingStatus('Usando modo linha direta');
      }
    } finally {
      setIsCalculatingRoute(false);
      fetchControllerRef.current = null;
    }
  };

  // GPS PERSISTENTE
  useEffect(() => {
    if (!("geolocation" in navigator)) return;

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { role, isActive, plannedRoute, destination, tripCode, isConfiguring } = navDataRef.current;
        const newPoint = { lat: position.coords.latitude, lng: position.coords.longitude, timestamp: Date.now() };
        setUserPos(newPoint);

        if (role === UserRole.MESTRE && isActive && tripCode) {
          if (!lastRecordedPosRef.current || calculateDistance(lastRecordedPosRef.current, newPoint) > 15) {
            storageService.updateTripPath(tripCode, newPoint);
            lastRecordedPosRef.current = newPoint;
          }
        }

        // Auto-recalculo apenas se for Mestre e estiver REALMENTE longe
        if (role === UserRole.MESTRE && isActive && plannedRoute.length > 5 && destination) {
          if (!isPointNearRoute(newPoint, plannedRoute, 200)) {
            if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
            debounceTimerRef.current = setTimeout(() => fetchRoadRoute(newPoint, destination), 3000);
          }
        }
      },
      null,
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );

    return () => { if (watchIdRef.current) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, []);

  // Busca Gemini
  useEffect(() => {
    if (selectedDest && searchQuery === selectedDest.name) return;
    if (searchQuery.length < 3) { setSuggestions([]); return; }
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const resp = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `5 locais para: "${searchQuery}" perto de ${userPos?.lat}, ${userPos?.lng}. JSON real: name, address, lat, lng.`,
          config: { responseMimeType: "application/json" }
        });
        if (resp?.text) setSuggestions(JSON.parse(resp.text));
      } catch (e) { console.error(e); } finally { setIsSearching(false); }
    }, 1000);
  }, [searchQuery]);

  // Trata seleção de destino
  useEffect(() => {
    if (selectedDest && userPos && isConfiguringTrip) {
      fetchRoadRoute(userPos, selectedDest);
    }
  }, [selectedDest, isConfiguringTrip]);

  const handleStartTrip = () => {
    if (!selectedDest) return;
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: `Comboio ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(false);
    speak("Comboio iniciado com sucesso.");
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center animate-in fade-in zoom-in duration-500">
          <div className="bg-blue-600 w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-[0_0_40px_rgba(37,99,235,0.3)]">
            <Navigation size={48} className="text-white" />
          </div>
          <h1 className="text-5xl font-black mb-3 tracking-tighter">Siga o Mestre</h1>
          <p className="text-slate-400 text-lg">Seu grupo sempre unido.</p>
        </div>
        <div className="w-full max-w-sm space-y-4">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 text-white font-bold py-6 px-6 rounded-3xl flex items-center justify-between shadow-xl active:scale-95 transition-all">
            <div className="flex items-center"><Play size={28} className="mr-4 fill-white"/> Criar Novo Comboio</div>
            <Zap size={20} className="text-blue-200" />
          </button>
          <div className="relative py-4"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div><div className="relative flex justify-center text-xs text-slate-500 uppercase font-black"><span className="bg-[#0f172a] px-4">Entrar em Grupo</span></div></div>
          <input type="text" placeholder="CÓDIGO" className="w-full bg-slate-800 border-2 border-slate-700 rounded-2xl px-5 py-5 text-white uppercase text-center text-2xl font-mono font-black tracking-widest outline-none focus:border-blue-500 transition-all" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
          <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); setPlannedRoute(trip.plannedRoute || []); setIsBottomSheetOpen(false); }else{ setError("Código inválido."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-black py-5 px-6 rounded-2xl flex items-center justify-center active:scale-95 transition-all shadow-xl">
             Entrar como Seguidor
          </button>
          {error && <div className="text-red-400 text-sm font-bold bg-red-500/10 p-4 rounded-xl border border-red-500/20 text-center">{error}</div>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white overflow-hidden z-[2000]">
        <div className="h-16 bg-slate-900 text-white flex items-center px-4 shrink-0 z-[3000]">
          <button onClick={() => { setIsConfiguringTrip(false); setSelectedDest(null); setPlannedRoute([]); if(fetchControllerRef.current) fetchControllerRef.current.abort(); }} className="flex items-center text-slate-400 font-bold"><ArrowLeft className="mr-2" size={20} /> Cancelar</button>
          <div className="flex-1 text-center font-black">Destino do Grupo</div>
          <div className="w-10"></div>
        </div>
        <div className="flex-grow relative w-full overflow-hidden">
          <MapComponent 
            userPos={userPos} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => { setSelectedDest({ lat, lng, name: "Ponto Selecionado" }); setPlannedRoute([]); }}
            isSelectingDestination={true} masterPos={null}
          />
          <div className="absolute top-4 left-4 right-4 z-[4000]">
            <div className="relative flex shadow-2xl bg-white rounded-2xl overflow-hidden border border-slate-100 p-1">
              <div className="flex items-center pl-4 text-slate-400">{isSearching ? <Loader2 size={24} className="animate-spin text-blue-500" /> : <Search size={24} />}</div>
