      id: Date.now().toString(),
      code,
      name: `Comboio para ${selectedDest.name}`,
      masterId: "me",
      destination: selectedDest,
      plannedRoute: plannedRoute, // Pode ser a linha reta ou ruas, o mapa aceita ambos
      path: userPos ? [userPos] : [],
